/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: storedCredit, isInvalidPhraseError
 *   Constants: artistId, featuredId, organizationId, thirdArtistId
 * Tests
 *   - normalizes ordered Credits and preserves only valid legacy projections
 *   - rejects invalid subject-role pairs, duplicates, and contradictory attribution
 *   - classifies one Artist Album relationship with deterministic precedence
 *   - migration Credit IDs are stable and intent-specific
 *   - legacy artist edits preserve known roles and Organization Credits
 *   - a join phrase accepts short visible text, keeps surrounding spaces, and is NFC normalized
 *   - a join phrase rejects empty, invisible, control, separator, lone-surrogate, long, and non-string values
 *   - phrase-free Credits keep exactly five keys and their current bytes
 *   - stored Credit reads drop invalid phrases but keep every structural check
 *   - legacy artist edits keep retained join phrases and tolerate an invalid one
 *   - stored join phrases are retained only by a matching creditId
 *   - inherited Album primary Credits keep a phrase only when the next Album Credit is inherited too
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';

import {
    CatalogCreditValidationError,
    classifyArtistAlbumCredit,
    inheritedAlbumPrimaryCredits,
    invalidStoredJoinPhraseCreditIds,
    legacyAlbumArtistIdsFromCredits,
    legacyTrackArtistIdsFromCredits,
    mergeLegacyArtistIdsIntoCredits,
    migratedCatalogCreditId,
    normalizeCatalogCredits,
    normalizeJoinPhrase,
    normalizeStoredCatalogCredits,
    retainStoredJoinPhrases,
    storedJoinPhrase,
    validateAttribution,
    withoutJoinPhrase
} from '../../src/models/catalogCredit';

const artistId = '64b000000000000000000001';
const featuredId = '64b000000000000000000002';
const organizationId = '64b000000000000000000003';

test('normalizes ordered Credits and preserves only valid legacy projections', () => {
    const credits = normalizeCatalogCredits([
        { creditId: 'credit_primary', subjectType: 'artist', subjectId: artistId.toUpperCase(), role: 'primary', order: 12 },
        { creditId: 'credit_featured', subjectType: 'artist', subjectId: featuredId, role: 'featured', order: 0 },
        { creditId: 'credit_label', subjectType: 'organization', subjectId: organizationId, role: 'label', order: 4 }
    ]);
    assert.deepEqual(credits.map((credit) => credit.order), [0, 1, 2]);
    assert.deepEqual(legacyTrackArtistIdsFromCredits(credits), [artistId, featuredId]);
    assert.deepEqual(legacyAlbumArtistIdsFromCredits(credits), [artistId]);
    assert.equal(validateAttribution('documented', credits), 'documented');
});

test('rejects invalid subject-role pairs, duplicates, and contradictory attribution', () => {
    assert.throws(() => normalizeCatalogCredits([
        { creditId: 'credit_invalid', subjectType: 'organization', subjectId: organizationId, role: 'primary', order: 0 }
    ]), CatalogCreditValidationError);
    assert.throws(() => normalizeCatalogCredits([
        { creditId: 'credit_first', subjectType: 'artist', subjectId: artistId, role: 'primary', order: 0 },
        { creditId: 'credit_second', subjectType: 'artist', subjectId: artistId, role: 'primary', order: 1 }
    ]), /Duplicate subject/);
    assert.throws(() => validateAttribution('documented', []), /requires at least one Credit/);
    assert.throws(() => validateAttribution('unknown', normalizeCatalogCredits([
        { creditId: 'credit_primary', subjectType: 'artist', subjectId: artistId, role: 'primary', order: 0 }
    ])), /cannot contain documented Credits/);
});

test('classifies one Artist Album relationship with deterministic precedence', () => {
    const primary = normalizeCatalogCredits([
        { creditId: 'credit_primary', subjectType: 'artist', subjectId: artistId, role: 'primary', order: 0 }
    ]);
    const featuredTrack = normalizeCatalogCredits([
        { creditId: 'credit_featured', subjectType: 'artist', subjectId: artistId, role: 'featured', order: 0 }
    ]);
    assert.equal(classifyArtistAlbumCredit(artistId, primary, featuredTrack), 'discography');
    assert.equal(classifyArtistAlbumCredit(artistId, [], featuredTrack), 'appearsOn');
    assert.equal(classifyArtistAlbumCredit(artistId, normalizeCatalogCredits([
        { creditId: 'credit_producer', subjectType: 'artist', subjectId: artistId, role: 'producer', order: 0 }
    ]), []), 'credits');
    assert.equal(classifyArtistAlbumCredit(featuredId, primary, featuredTrack), null);
});

test('migration Credit IDs are stable and intent-specific', () => {
    const first = migratedCatalogCreditId('album', '64b000000000000000000004', 'artist', artistId, 'primary');
    assert.equal(first, migratedCatalogCreditId('album', '64b000000000000000000004', 'artist', artistId, 'primary'));
    assert.notEqual(first, migratedCatalogCreditId('audioTrack', '64b000000000000000000004', 'artist', artistId, 'primary'));
});

test('legacy artist edits preserve known roles and Organization Credits', () => {
    const existing = normalizeCatalogCredits([
        { creditId: 'credit_primary', subjectType: 'artist', subjectId: artistId, role: 'primary' },
        { creditId: 'credit_removed', subjectType: 'artist', subjectId: featuredId, role: 'featured' },
        { creditId: 'credit_label', subjectType: 'organization', subjectId: organizationId, role: 'label' }
    ]);
    const addedId = '64b000000000000000000004';
    const merged = mergeLegacyArtistIdsIntoCredits(
        'audioTrack',
        '64b000000000000000000005',
        existing,
        [artistId, addedId]
    );
    assert.deepEqual(merged.map((credit) => [credit.subjectId, credit.role]), [
        [artistId, 'primary'],
        [addedId, 'legacyUnspecified'],
        [organizationId, 'label']
    ]);
});

// Join phrases. Invisible and combining characters are written as escapes.
const thirdArtistId = '64b000000000000000000007';
const storedCredit = (
    creditId: string,
    subjectId: string,
    role: string,
    extra: Record<string, unknown> = {}
) => ({
    creditId,
    subjectType: subjectId === organizationId ? 'organization' : 'artist',
    subjectId,
    role,
    order: 0,
    ...extra
});
const isInvalidPhraseError = (error: unknown) => error instanceof CatalogCreditValidationError
    && error.message === 'Credit joinPhrase is invalid.';

test('a join phrase accepts short visible text, keeps surrounding spaces, and is NFC normalized', () => {
    const acceptedPhrases = [
        '\u3001', ' & ', ' feat. ', '&', '\u00A0&\u00A0', 'x'.repeat(16), '\u{1F3BB}'.repeat(8),
        // A variation selector after a visible character, and a flag set off by spaces.
        '\u2764\uFE0F', ' \u{1F1EF}\u{1F1F5} '
    ];
    for (const phrase of acceptedPhrases) {
        assert.equal(normalizeJoinPhrase(phrase), phrase, JSON.stringify(phrase));
    }
    assert.equal('\u{1F3BB}'.repeat(8).length, 16);
    assert.equal(normalizeJoinPhrase(undefined), undefined);
    assert.equal(normalizeJoinPhrase(' ve\u0301s '), ' v\u00E9s ');
    // 17 UTF-16 units before composition, 16 after.
    const decomposed = `${'x'.repeat(15)}e\u0301`;
    assert.equal(decomposed.length, 17);
    assert.equal(normalizeJoinPhrase(decomposed), `${'x'.repeat(15)}\u00E9`);
});

test('a join phrase rejects empty, invisible, control, separator, lone-surrogate, long, and non-string values', () => {
    const rejectedValues: unknown[] = [
        // Empty or whitespace only, a lone combining mark, and the invisible Hangul filler.
        '', ' ', '\u3000', ' \u0301 ', '\u3164',
        // Format characters.
        'a\u200Bb', 'a\u200Eb', 'a\u2060b', '\uFEFF&', 'a\u00ADb', 'a\u200Db',
        // Controls and line or paragraph separators.
        '\t&', '&\n', 'a\u0000b', 'a\u007Fb', 'a\u0085b', 'a\u2028b', 'a\u2029b',
        // Lone surrogates.
        'a\uD800b', '\uDC00&',
        // Edges that fuse with the neighboring name: a leading combining mark, variation
        // selector, emoji modifier, regional indicator or Hangul medial or final jamo, and a
        // trailing regional indicator or Hangul initial jamo.
        '\u0301 & ', '\u0308 & ', '\uFE0F&', '\u{1F3FD}&', '\u{1F1EF}', '\u{1F1EF}\u{1F1F5}', '&\u{1F1EF}',
        '\u1161&', '\u11A8&', '&\u1100',
        // Private-use, unassigned and noncharacter code points.
        '\uE000', '&\uE000', '\u0378', '\uFFFF', '\uFDD0&',
        // Blank-rendering characters, alone or next to a visible character.
        '\u2800', '&\u2800', '&\u3164', '\u3164&\u3164', '&\u034F', '\uFFA0&', 'a\u115Fb', '&\u17B4',
        // Too long.
        'x'.repeat(17), '\u{1F3BB}'.repeat(9),
        // Not a string.
        null, 3, {}
    ];
    for (const value of rejectedValues) {
        assert.throws(() => normalizeJoinPhrase(value), isInvalidPhraseError, JSON.stringify(value));
        assert.equal(storedJoinPhrase(value), undefined, JSON.stringify(value));
    }
});

test('phrase-free Credits keep exactly five keys and their current bytes', () => {
    const credits = normalizeCatalogCredits([
        storedCredit('credit_primary', artistId, 'primary'),
        storedCredit('credit_label', organizationId, 'label', { musicBrainzId: 'synthetic' })
    ]);
    for (const credit of credits) {
        assert.deepEqual(Object.keys(credit), ['creditId', 'subjectType', 'subjectId', 'role', 'order']);
        assert.equal('joinPhrase' in credit, false);
    }
    assert.equal(JSON.stringify(credits), '[{"creditId":"credit_primary","subjectType":"artist",'
        + `"subjectId":"${artistId}","role":"primary","order":0},{"creditId":"credit_label",`
        + `"subjectType":"organization","subjectId":"${organizationId}","role":"label","order":1}]`);

    const [withPhrase] = normalizeCatalogCredits([storedCredit('credit_primary', artistId, 'primary', { joinPhrase: ' & ' })]);
    assert.deepEqual(Object.keys(withPhrase), ['creditId', 'subjectType', 'subjectId', 'role', 'order', 'joinPhrase']);
    assert.equal(withPhrase.joinPhrase, ' & ');
    assert.deepEqual(Object.keys(withoutJoinPhrase(withPhrase)), ['creditId', 'subjectType', 'subjectId', 'role', 'order']);
    assert.throws(() => normalizeCatalogCredits([
        storedCredit('credit_primary', artistId, 'primary', { joinPhrase: '\u200B' })
    ]), isInvalidPhraseError);
    // Structural errors keep their precedence over a bad phrase in the same Credit.
    assert.throws(() => normalizeCatalogCredits([
        storedCredit('short', artistId, 'primary', { joinPhrase: '\u200B' })
    ]), /creditId is invalid/);
});

test('stored Credit reads drop invalid phrases but keep every structural check', () => {
    const stored = [
        storedCredit('credit_first', artistId, 'primary', { joinPhrase: ' & ' }),
        storedCredit('credit_second', featuredId, 'primary', { joinPhrase: 'x\u200By' }),
        storedCredit('credit_third', organizationId, 'label', { joinPhrase: null })
    ];
    const credits = normalizeStoredCatalogCredits(stored);
    assert.deepEqual(credits.map((credit) => credit.joinPhrase), [' & ', undefined, undefined]);
    assert.deepEqual(credits.map((credit) => 'joinPhrase' in credit), [true, false, false]);
    assert.deepEqual(invalidStoredJoinPhraseCreditIds(stored), ['credit_second', 'credit_third']);
    assert.deepEqual(invalidStoredJoinPhraseCreditIds(credits), []);
    assert.deepEqual(invalidStoredJoinPhraseCreditIds('not a list'), []);
    assert.throws(() => normalizeCatalogCredits(stored), isInvalidPhraseError);

    assert.throws(() => normalizeStoredCatalogCredits({}), /must be an array/);
    assert.throws(() => normalizeStoredCatalogCredits([
        storedCredit('credit_first', artistId, 'label', { joinPhrase: '\u200B' })
    ]), /not valid for artist/);
    assert.throws(() => normalizeStoredCatalogCredits([
        storedCredit('credit_first', artistId, 'primary', { joinPhrase: ' & ' }),
        storedCredit('credit_first', featuredId, 'primary')
    ]), /unique/);
    assert.throws(() => normalizeStoredCatalogCredits(Array.from({ length: 51 }, (_, index) =>
        storedCredit(`credit_${String(index).padStart(3, '0')}`, artistId, 'primary'))), /No more than 50/);
});

test('legacy artist edits keep retained join phrases and tolerate an invalid one', () => {
    const merged = mergeLegacyArtistIdsIntoCredits('audioTrack', '64b000000000000000000005', [
        storedCredit('credit_primary', artistId, 'primary', { joinPhrase: ' & ' }),
        storedCredit('credit_featured', featuredId, 'featured', { joinPhrase: '\u200B' }),
        storedCredit('credit_removed', thirdArtistId, 'primary', { joinPhrase: ' / ' }),
        storedCredit('credit_label', organizationId, 'label', { joinPhrase: ' / ' })
    ], [artistId, featuredId]);
    assert.deepEqual(merged.map((credit) => [credit.creditId, credit.joinPhrase]), [
        ['credit_primary', ' & '],
        ['credit_featured', undefined],
        ['credit_label', ' / ']
    ]);
});

test('stored join phrases are retained only by a matching creditId', () => {
    const stored = normalizeCatalogCredits([
        storedCredit('credit_primary', artistId, 'primary', { joinPhrase: ' & ' }),
        storedCredit('credit_featured', featuredId, 'featured', { joinPhrase: ' feat. ' }),
        storedCredit('credit_label', organizationId, 'label')
    ]);
    const edited = { ...storedCredit('credit_featured', featuredId, 'primary') };
    const unknown = storedCredit('credit_unknown', thirdArtistId, 'primary');
    const label = storedCredit('credit_label', organizationId, 'label');
    const retained = retainStoredJoinPhrases([edited, unknown, label, 'not a Credit', null], stored) as unknown[];
    assert.deepEqual(retained[0], { ...edited, joinPhrase: ' feat. ' });
    assert.equal(retained[1], unknown);
    assert.equal(retained[2], label);
    assert.equal(retained[3], 'not a Credit');
    assert.equal(retained[4], null);
    assert.equal(retainStoredJoinPhrases('not a list', stored), 'not a list');
});

test('inherited Album primary Credits keep a phrase only when the next Album Credit is inherited too', () => {
    const trackId = '64b000000000000000000006';
    const trackCreditId = (subjectId: string) =>
        migratedCatalogCreditId('audioTrack', trackId, 'artist', subjectId, 'primary');
    const albumCredits = [
        storedCredit('album_primary_a', artistId, 'primary', { joinPhrase: ' & ' }),
        storedCredit('album_primary_b', featuredId, 'primary', { joinPhrase: ' feat. ' }),
        storedCredit('album_featured_c', thirdArtistId, 'featured')
    ];
    const inherited = inheritedAlbumPrimaryCredits(trackId, albumCredits);
    assert.deepEqual(inherited, [
        { creditId: trackCreditId(artistId), subjectType: 'artist', subjectId: artistId, role: 'primary', order: 0, joinPhrase: ' & ' },
        { creditId: trackCreditId(featuredId), subjectType: 'artist', subjectId: featuredId, role: 'primary', order: 0 }
    ]);
    assert.equal('joinPhrase' in inherited[1], false);

    const invalid = inheritedAlbumPrimaryCredits(trackId, [
        storedCredit('album_primary_a', artistId, 'primary', { joinPhrase: 'x\u200By' }),
        albumCredits[1]
    ]);
    assert.deepEqual(invalid.map((credit) => 'joinPhrase' in credit), [false, false]);
    assert.deepEqual(inheritedAlbumPrimaryCredits(trackId, [albumCredits[0]]).map((credit) => 'joinPhrase' in credit), [false]);

    // `feat.` was written before the featured Artist, which a MediaTrack does not inherit, so it
    // must not end up joining the two inherited primary Artists.
    const skipped = inheritedAlbumPrimaryCredits(trackId, [
        storedCredit('album_primary_a', artistId, 'primary', { joinPhrase: ' feat. ' }),
        storedCredit('album_featured_x', featuredId, 'featured'),
        storedCredit('album_primary_b', thirdArtistId, 'primary')
    ]);
    assert.deepEqual(skipped.map((credit) => credit.subjectId), [artistId, thirdArtistId]);
    assert.deepEqual(skipped.map((credit) => 'joinPhrase' in credit), [false, false]);
    assert.deepEqual(inheritedAlbumPrimaryCredits(trackId, undefined), []);
    assert.deepEqual(inheritedAlbumPrimaryCredits(trackId, { credits: albumCredits }), []);
});
